// ===========================================================================
// INF2003 G61 - MedSafety database: MongoDB SETUP (MongoDB 7.0+, mongosh)
// ===========================================================================
// Builds the 5 MongoDB collections with validation rules, indexes and demo data:
//   encounters          one document per clinic visit: triage (vitals, complaint, pain)
//                       + the doctor's consultation note
//   patient_history     one document per history fact: smoking, alcohol, past conditions,
//                       procedures, family history. A change is a new event; the old one
//                       is closed (status "superseded", effectivePeriod.end set)
//   lab_results         one document per lab result (value, unit, normal range, flag)
//   prescription_audit  one document per prescription: alerts shown when it was written,
//                       and every doctor / pharmacist decision (events array)
//   lab_rules           which recent lab values make a drug risky (used by the safety check)
//
// The data matches medsafety_setup_postgres.sql: same patients (nric), diagnosisId,
// prescriptionId, doctorId and pharmacistId. Dates are relative to the day you run this,
// just like the PostgreSQL script, so RUN BOTH SCRIPTS ON THE SAME DAY (re-run both
// before a demo).
//
// WARNING: drops and rebuilds these 5 collections in the "medsafety" database.
//
// HOW TO RUN
//   Terminal:  mongosh medsafety_setup_mongo.js
//   Compass:   open the MONGOSH tab at the bottom, then
//              load("C:/full/path/to/medsafety_setup_mongo.js")      (use forward slashes)
// The last thing it prints is a CHECK table: every row should say PASS.
// ===========================================================================

db = db.getSiblingDB("medsafety");

// ---------------------------------------------------------------------------
// Dates: the data stores {"$days": n, "$min": m} = n days from today, m minutes after
// midnight; {"$days": 0, "$agoMin": m} = m minutes before now (for today's records).
// ---------------------------------------------------------------------------
const RUN_AT = new Date();
const TODAY = new Date(RUN_AT); TODAY.setHours(0, 0, 0, 0);
function toDate(spec) {
  if (spec.$agoMin !== undefined) return new Date(RUN_AT.getTime() - spec.$agoMin * 60000);
  const d = new Date(TODAY);
  d.setDate(d.getDate() + spec.$days);
  return new Date(d.getTime() + (spec.$min || 0) * 60000);
}
function fixDates(v) {
  if (Array.isArray(v)) return v.map(fixDates);
  if (v && typeof v === "object") {
    if ("$days" in v) return toDate(v);
    const o = {};
    for (const k of Object.keys(v)) o[k] = fixDates(v[k]);
    return o;
  }
  return v;
}

// ---------------------------------------------------------------------------
// 1. Drop old collections
// ---------------------------------------------------------------------------
["encounters", "patient_history", "lab_results", "prescription_audit", "lab_rules"].forEach(c => db.getCollection(c).drop());

// ---------------------------------------------------------------------------
// 2. Collections with $jsonSchema validation
//    Required fields and types are enforced; extra fields are allowed on purpose
//    (e.g. history details differ per event type, targetRange only on warfarin INR results).
// ---------------------------------------------------------------------------
// Whole numbers may arrive as int (mongosh, Node) or long (some drivers); allow both.
const INT = ["int", "long"];
const NUM = ["int", "long", "double", "decimal"];

const person = (role) => ({
  bsonType: "object", required: ["role", "id", "name"],
  properties: { role: { enum: [role] }, id: { bsonType: INT, minimum: 1 }, name: { bsonType: "string" } }
});

db.createCollection("encounters", {
  validator: { $jsonSchema: {
    bsonType: "object",
    required: ["_id", "nric", "visitDate", "visitType", "doctor", "triage", "consultation"],
    properties: {
      _id: { bsonType: "string", pattern: "^E[0-9]{4,}$" },
      nric: { bsonType: "string", pattern: "^[STFGM][0-9]{7}[A-Z]$", description: "Patient.NRIC in PostgreSQL" },
      visitDate: { bsonType: "date" },
      visitType: { enum: ["new problem", "follow-up"] },
      doctor: { bsonType: "object", required: ["doctorId", "name"],
                properties: { doctorId: { bsonType: INT }, name: { bsonType: "string" }, hospital: { bsonType: "string" } } },
      triage: {
        bsonType: "object", required: ["recordedAt", "category", "chiefComplaint", "vitals"],
        properties: {
          recordedAt: { bsonType: "date" },
          category: { enum: ["P1", "P2", "P3", "P4"], description: "Singapore Patient Acuity Category" },
          chiefComplaint: { bsonType: "string", minLength: 3 },
          painScore: { bsonType: INT, minimum: 0, maximum: 10 },
          vitals: {
            bsonType: "object", required: ["systolicBP", "diastolicBP", "heartRate", "temperatureC", "spo2"],
            properties: {
              systolicBP: { bsonType: INT, minimum: 50, maximum: 260 },
              diastolicBP: { bsonType: INT, minimum: 20, maximum: 160 },
              heartRate: { bsonType: INT, minimum: 20, maximum: 250 },
              respRate: { bsonType: INT, minimum: 4, maximum: 60 },
              temperatureC: { bsonType: NUM, minimum: 30, maximum: 44 },
              spo2: { bsonType: INT, minimum: 50, maximum: 100 },
              weightKg: { bsonType: NUM, minimum: 1, maximum: 400 }
            }
          }
        }
      },
      consultation: {
        bsonType: "object", required: ["note", "diagnosisIds"],
        properties: {
          note: { bsonType: "string", minLength: 10 },
          diagnosisIds: { bsonType: "array", minItems: 1, items: { bsonType: INT }, description: "Diagnosis.DiagnosisID in PostgreSQL" },
          followUpInDays: { bsonType: INT, minimum: 1 }
        }
      },
      prescriptionIds: { bsonType: "array", items: { bsonType: INT } }
    }
  } },
  validationLevel: "strict", validationAction: "error"
});

// patient_history: the required fields depend on eventType (oneOf = exactly one shape matches)
const period = { bsonType: "object", required: ["start", "end"],
                 properties: { start: { bsonType: "date" }, end: { bsonType: ["date", "null"] } } };
const code = { bsonType: "object", required: ["system", "value", "display"],
               properties: { system: { bsonType: "string" }, value: { bsonType: "string" }, display: { bsonType: "string" } } };
db.createCollection("patient_history", {
  validator: { $jsonSchema: {
    bsonType: "object",
    required: ["_id", "nric", "eventType", "status", "effectivePeriod", "recordedAt", "verificationStatus", "details", "schemaVersion"],
    properties: {
      _id: { bsonType: "string", pattern: "^H[0-9]{4,}$" },
      nric: { bsonType: "string", pattern: "^[STFGM][0-9]{7}[A-Z]$", description: "Patient.NRIC in PostgreSQL" },
      eventType: { enum: ["social_history", "condition", "procedure", "family_history"] },
      effectivePeriod: period,
      recordedAt: { bsonType: "date" },
      recordedBy: person("doctor"),
      encounterId: { bsonType: "string" },
      verificationStatus: { enum: ["patient_reported", "clinician_confirmed", "external_record"] },
      details: { bsonType: "object" },
      schemaVersion: { bsonType: INT, minimum: 1 }
    },
    oneOf: [
      { properties: {   // smoking
          eventType: { enum: ["social_history"] }, category: { enum: ["smoking"] },
          status: { enum: ["active", "superseded", "entered_in_error"] },
          details: { required: ["smokingStatus"], properties: {
            smokingStatus: { enum: ["never_smoker", "current_smoker", "former_smoker"] },
            cigarettesPerDay: { bsonType: INT, minimum: 0 }, yearsSmoked: { bsonType: INT, minimum: 0 },
            packYears: { bsonType: NUM, minimum: 0 }, quitDate: { bsonType: "date" } } } },
        required: ["category"] },
      { properties: {   // alcohol
          eventType: { enum: ["social_history"] }, category: { enum: ["alcohol"] },
          status: { enum: ["active", "superseded", "entered_in_error"] },
          details: { required: ["alcoholUse"], properties: { unitsPerWeek: { bsonType: NUM, minimum: 0 } } } },
        required: ["category"] },
      { properties: {   // past or external condition
          eventType: { enum: ["condition"] }, status: { enum: ["active", "resolved", "entered_in_error"] }, code: code },
        required: ["code"] },
      { properties: {   // procedure / surgery
          eventType: { enum: ["procedure"] }, status: { enum: ["completed", "entered_in_error"] }, code: code },
        required: ["code"] },
      { properties: {   // family history
          eventType: { enum: ["family_history"] }, status: { enum: ["active", "entered_in_error"] }, code: code,
          details: { required: ["relation"], properties: { relation: { enum: ["father", "mother", "sibling", "child", "grandparent"] } } } },
        required: ["code"] }
    ]
  } },
  validationLevel: "strict", validationAction: "error"
});

db.createCollection("lab_results", {
  validator: { $jsonSchema: {
    bsonType: "object",
    required: ["nric", "test", "testName", "value", "unit", "refRange", "flag", "collectedAt"],
    properties: {
      nric: { bsonType: "string", pattern: "^[STFGM][0-9]{7}[A-Z]$" },
      test: { enum: ["POTASSIUM", "SODIUM", "CREATININE", "EGFR", "HBA1C", "LDL", "ALT", "INR", "TSH", "URIC_ACID", "WBC", "CRP"] },
      testName: { bsonType: "string" },
      value: { bsonType: NUM, minimum: 0 },
      unit: { bsonType: "string" },
      refRange: { bsonType: "object", properties: { low: { bsonType: NUM }, high: { bsonType: NUM } } },
      targetRange: { bsonType: "object", required: ["low", "high"] },
      flag: { enum: ["L", "N", "H"] },
      collectedAt: { bsonType: "date" },
      orderedBy: { bsonType: INT },
      encounterId: { bsonType: "string" }
    }
  } },
  validationLevel: "strict", validationAction: "error"
});

db.createCollection("prescription_audit", {
  validator: { $and: [ { $jsonSchema: {
    bsonType: "object",
    required: ["_id", "nric", "diagnosisId", "drug", "prescribedBy", "status", "alerts", "events"],
    properties: {
      _id: { bsonType: INT, minimum: 1, description: "Prescription.PrescriptionID in PostgreSQL" },
      nric: { bsonType: "string", pattern: "^[STFGM][0-9]{7}[A-Z]$" },
      diagnosisId: { bsonType: INT },
      encounterId: { bsonType: "string" },
      drug: { bsonType: "object", required: ["drugId", "name"] },
      prescribedBy: { bsonType: "object", required: ["doctorId", "name"] },
      status: { enum: ["Pending", "Approved", "Rejected"], description: "mirror of Prescription.ReviewStatus" },
      alerts: {
        bsonType: "array",
        items: {
          bsonType: "object", required: ["type", "severity", "message"],
          properties: {
            type: { enum: ["interaction", "allergy", "lab", "duplicate"] },
            severity: { enum: ["avoid", "caution", "mild", "moderate", "severe", "major"] },
            message: { bsonType: "string" }
          }
        }
      },
      events: {
        bsonType: "array", minItems: 1,
        items: {
          bsonType: "object", required: ["at", "action", "by"],
          properties: {
            at: { bsonType: "date" },
            action: { enum: ["prescribed", "approved", "rejected", "cancelled"] },
            by: { oneOf: [person("doctor"), person("pharmacist")] },
            reason: { bsonType: "string" },
            note: { bsonType: "string" }
          }
        }
      }
    }
  } },
  // Rule beyond the schema: a rejected prescription must carry a "rejected" event with a note.
  { $or: [ { status: { $ne: "Rejected" } },
           { events: { $elemMatch: { action: "rejected", note: { $type: "string", $ne: "" } } } } ] }
  ] },
  validationLevel: "strict", validationAction: "error"
});

db.createCollection("lab_rules", {
  validator: { $jsonSchema: {
    bsonType: "object",
    required: ["_id", "ingredients", "test", "op", "threshold", "withinDays", "severity", "message"],
    properties: {
      ingredients: { bsonType: "array", minItems: 1, items: { bsonType: "string" }, description: "ActiveIngredients.IngredientName in PostgreSQL" },
      test: { bsonType: "string" },
      op: { enum: ["gt", "lt"] },
      threshold: { bsonType: NUM },
      withinDays: { bsonType: INT, minimum: 1 },
      severity: { enum: ["moderate", "major"] },
      message: { bsonType: "string" }
    }
  } },
  validationLevel: "strict", validationAction: "error"
});

